INSERT INTO public."serviceStatusHistory" VALUES ('a310a261-bf11-4375-93fb-a73b17ce1ef4', 'SEYMLA0SYF', NULL, 'custom', 'আই পি এসটির ত্রুটি সারানেরার কাজ চলছে', 'আপনার আই পি এসটির যে ত্রুটি দরা পরেছে তা সারানোর কাজ শুরু করেছে আশা করছি নতুন পাটর্স গুলা পরির্বতন করলে আই পি এসটি রানিং হয়ে যাবে ,সময় দিয়ে সহযোগীতা করবেন ধন্যবাদ।', NULL, '2026-02-16 08:31:09.778595+00', '2026-02-16 08:31:09.778595+00');
