INSERT INTO public."serviceStatusHistory" VALUES ('1ae18898-cc9f-4177-bc7e-be0df2435479', 'SEYMLA0SYF', NULL, 'custom', 'সার্ভিসিং সেন্টার রিসিভ করা হয়েছে ', 'আপনার আই পি এস টি আমাদের অফিসিয়াল  সার্ভিসিং সেন্টার রিসিভ করা হয়েছে আপনার পন্যটির সমস্যা সমাধানের জন্য দক্ষ ইঞ্জিনিয়ার টিম এসাইন্ড করা হবে। সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ। ', NULL, '2026-02-15 12:58:38.788807+00', '2026-02-15 14:36:01.503+00');
INSERT INTO public."serviceStatusHistory" VALUES ('e3cde86a-04c9-41b3-8392-9d11a1469f2a', 'SEYMLA0SYF', NULL, 'custom', 'পন্যটির সমস্যা সমাধানে পরিক্ষা শুরু  করেছে', 'আপনার আই পি এস টি আমাদের অফিসিয়াল দক্ষ ইঞ্জিনিয়ার টিম পরিক্ষা নিরিক্ষার কাজ শুরু করেছে আশা করছি খুব দ্রুত সমস্যাটি খুঁজে বের করবে। সেই পর্যন্ত আমাদের সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ', NULL, '2026-02-15 14:41:25.768415+00', '2026-02-15 14:41:25.768415+00');
INSERT INTO public."serviceStatusHistory" VALUES ('82e9be0d-c586-409a-a38f-89622729d350', 'SEYMLA0SYF', NULL, 'custom', 'আপনার পন্যটির সমস্যা খুঁজে বের করা হয়েছে', 'আপনার আই পি এস টির ত্রুটি খুঁজে বের করা হয়েছে আমাদের সার্ভিস টিম খুব দ্রুত সমাধান করে আপ পি এস টি রানিং করবে,  আমাদের সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ। ', NULL, '2026-02-15 18:23:18.333866+00', '2026-02-15 18:23:18.333866+00');
INSERT INTO public."serviceStatusHistory" VALUES ('1dc82e10-f085-4761-8a8a-2b69aad1eb15', 'SEYMLA0SYF', NULL, 'custom', 'এস ই ইলেকট্রনিকস সার্ভিসিং সেন্টার নোট', 'আপনার আই পি এসটির কাজ সম্পূর্ণ করা হয়েছে এখন বর্তমানে ওয়েটিং টেস্টে আছে টেস্টিং শেষ হলেই আপনাকে ডেলিভারি করা হবে সময় দিয়ে সহযোগীতা করবেন।', NULL, '2026-02-16 12:24:47.019942+00', '2026-02-16 12:24:47.019942+00');
