INSERT INTO public."serviceStatusHistory" VALUES ('3a731086-d545-43a9-8e3f-de26949ba072', 'SEYMLA0SYF', NULL, 'custom', 'সার্ভিস সেন্টার টেস্টিং সাকসেসফুল', 'প্রিয় গ্রাহক আপনার আই পি এস টি সম্পূর্ণভাবে সার্ভিসিং করে সকল প্রকারের টেস্টিং করা শেষ হয়েছে আমরা আপনার আই পি এস টি ডেলিভারি দিতে এস ই ইলেকট্রনিকস সার্ভিস সেন্টার প্রস্তুত আছে', NULL, '2026-02-16 19:01:24.584322+00', '2026-02-16 19:01:24.584322+00');
INSERT INTO public."serviceStatusHistory" VALUES ('956d420d-0278-4c04-8298-2f15e7b07eb2', 'SEYMLA0SYF', NULL, 'custom', 'সার্ভিস সেন্টার ডেলিভারী দিতে প্রস্তুত', 'প্রিয় গ্রাহক রাফছানুল, আপনার পন্যটির সার্ভিস আই ডি: SEYMLA0SYF আমাদের অফিসিয়াল সার্ভিস পয়েন্ট আই পি এসটি ডেলিভারী দিতে সম্পূর্ণ প্রস্তুত আছে আপনাকে অতি দ্রুত ডেলিভারী  নিতে অনুরোধ করা হল।', NULL, '2026-02-17 06:40:05.463151+00', '2026-02-17 06:40:05.463151+00');
