INSERT INTO public."serviceStatusHistory" VALUES ('e484a97d-21e8-4901-aa73-e69832aa40c2', 'SEWIH5AS37', NULL, 'custom', 'পন্যটির সমস্যা সমাধানে পরিক্ষা শুরু করেছে ‎', 'আপনার আই পি এস টি আমাদের অফিসিয়াল দক্ষ ইঞ্জিনিয়ার টিম পরিক্ষা নিরিক্ষার কাজ শুরু করেছে আশা করছি খুব দ্রুত সমস্যাটি খুঁজে বের করবে। সেই পর্যন্ত আমাদের সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ', NULL, '2026-04-28 19:18:10.343438+00', '2026-04-28 19:18:10.343438+00');
INSERT INTO public."serviceStatusHistory" VALUES ('e209f717-92b0-4207-9d65-dd72b9f638c8', 'SEWIH5AS37', NULL, 'custom', '‎আপনার পন্যটির সমস্যা খুঁজে বের করা হয়েছে', 'আপনার আই পি এস টির ত্রুটি খুঁজে বের করা হয়েছে আমাদের সার্ভিস টিম খুব দ্রুত সমাধান করে আই পি এস টি রানিং করবে, আমাদের সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ।', NULL, '2026-04-28 20:28:17.009843+00', '2026-04-28 20:30:21.826+00');
INSERT INTO public."serviceStatusHistory" VALUES ('488eeebb-d1ef-4dae-956d-2bcc4452ece5', 'SEWIH5AS37', NULL, 'custom', 'সার্ভিসিং সেন্টার অফিস কর্তৃপক্ষ আদেশ। ', 'সম্মানিত গ্রাহকের সাথে আলাপচারিতার মাধ্যমে আইপিএসটির সার্ভিসিং এর জন্য যেসব পার্ট চেঞ্জ করা লাগবে তার মূল্য নির্ধারণ করে কনফার্ম হলে সার্ভিস এর কাজ সামনের দিকে এগিয়ে নিবে ও নিয়োজিত ইঞ্জিনিয়ার আইপিএসটির কাজ সমাধান করবে। সেই পর্যন্ত সময়টি সাথে থাকুন ধন্যবাদ। ', NULL, '2026-04-28 20:35:38.842468+00', '2026-04-28 20:35:38.842468+00');
INSERT INTO public."serviceStatusHistory" VALUES ('b5ec32f4-b785-4658-a821-8dfe9c419108', 'SEWIH5AS37', NULL, 'custom', 'অফিস কর্তৃপক্ষ সার্ভিসিং করার অনুমতি দিয়েছে', 'সম্মানিত গ্রাহকের  আইপিএসটির সার্ভিসিং এর জন্য যেসব পার্ট চেঞ্জ করা লাগবে তার মূল্য দিতে সম্মতি দিয়েছেন  সার্ভিস এর কাজ সামনের দিকে এগিয়ে নিতে অফিস কর্তৃপক্ষ অনুমতি দিয়েছে ও নিয়োজিত ইঞ্জিনিয়ার আইপিএসটির কাজ দ্রুত সমাধান করবে। সেই পর্যন্ত সময়টি সাথে থাকুন ধন্যবাদ। 
INSERT INTO public."serviceStatusHistory" VALUES ('19b8e759-6919-4e85-8031-036ff2037b05', 'SEWIH5AS37', NULL, 'custom', 'আই পি এসটির ত্রুটি সারানেরার কাজ চলছে', 'আপনার আই পি এসটির যে ত্রুটি দরা পরেছে তা সারানোর কাজ শুরু করেছে আশা করছি নতুন পাটর্স গুলা পরির্বতন করলে আই পি এসটি রানিং হয়ে যাবে ,সময় দিয়ে সহযোগীতা করবেন ধন্যবাদ।', NULL, '2026-04-29 08:35:32.640637+00', '2026-04-29 08:35:32.640637+00');
INSERT INTO public."serviceStatusHistory" VALUES ('bd941365-7500-4faa-9e4d-4563f2ad39de', 'SEWIH5AS37', NULL, 'custom', 'এস ই ইলেকট্রনিকস সার্ভিসিং সেন্টার নোট', 'আপনার আই পি এসটির কাজ সম্পূর্ণ করা হয়েছে এখন বর্তমানে ওয়েটিং টেস্টে আছে টেস্টিং শেষ হলেই আপনাকে সার্ভিস ট্রেকিং এর মাধ্যমে জানানো হবে সময় দিয়ে সহযোগীতা করবেন।', NULL, '2026-04-29 09:19:21.256964+00', '2026-04-29 09:19:21.256964+00');
INSERT INTO public."serviceStatusHistory" VALUES ('4479d0c6-26a4-411a-b63e-fc06c2403c44', 'SEWIH5AS37', NULL, 'custom', 'সার্ভিস সেন্টার পন্যটির  টেস্টিং সাকসেসফুল', 'প্রিয় গ্রাহক আপনার আই পি এস টি সম্পূর্ণভাবে সার্ভিসিং করে সকল প্রকারের টেস্টিং করা শেষ হয়েছে আমরা আপনার আই পি এস টি ডেলিভারি দিতে এস ই ইলেকট্রনিকস সার্ভিস সেন্টার প্রস্তুত আছে', NULL, '2026-04-29 13:23:35.956161+00', '2026-04-29 13:23:35.956161+00');
INSERT INTO public."serviceStatusHistory" VALUES ('fc0dd2b6-2f7c-46a1-9147-a7058fa59b29', 'SEWIH5AS37', NULL, 'custom', 'সার্ভিস সেন্টার পণ্যটি ডেলিভারী দিতে প্রস্তুত', 'প্রিয় গ্রাহক ANIK ROY, আপনার পন্যটির সার্ভিস আই ডি: SEWIH5AS37 আমাদের অফিসিয়াল সার্ভিস পয়েন্ট আই পি এসটি ডেলিভারী দিতে সম্পূর্ণ প্রস্তুত আছে আপনাকে অতি দ্রুত ডেলিভারী নিতে অনুরোধ করা হল।', NULL, '2026-04-29 13:27:10.39652+00', '2026-04-29 13:28:47.225+00');
INSERT INTO public."serviceStatusHistory" VALUES ('0263bcce-b6bc-406c-ac55-389c869b7e78', 'SEWIH5AS37', NULL, 'custom', 'আই পি এস টি ডেরিভারী নিতে অনুরোধ করা হল।', ' প্রিয় গ্রাহক আপনার পণ্যের সার্ভিস ডি: SEWIH5AS37, SMARTEN 1250 VA IPS সার্ভিস সেন্টার  বাদাম বাগিচা ২ নং রোড এস ই ইলেকট্রনিক্স সার্ভিস পয়েন্ট থেকে আই পি এসটি ডেলিভারী নিতে অনুরোধ করা হচ্ছে ধন্যবা', NULL, '2026-04-30 05:53:08.227406+00', '2026-04-30 05:59:25.163+00');
INSERT INTO public."serviceStatusHistory" VALUES ('ab8f1919-f24e-4bb6-aff2-7362119d580d', 'SEWIH5AS37', NULL, 'custom', 'এস ই ইলেকট্রনিকস সার্ভিসিং সেন্টার পলিসি', 'প্রিয় গ্রাহক ANIK ROY, আপনার পন্যটির সার্ভিস । সার্ভিস আই ডি: SEWIH5AS37 সার্ভিসিং এর SMARTEN 1250 VA IPSOVERLOAD PROVLEM  সমাধান করা হয়েছে 30/04/26, 2.00 PM  ডেলিভারি নিয়েছে আজ থেকে 2 দিনের মধ্যে পুনরায় OVERLOAD PROVLEM দেখা দিলে এস ই ইলেকট্রনিকস সার্ভিসিং সেন্টার আপনাকে পুনরায় বিনা মুল্য সার্ভিস করে দিবে, ধন্যবাদ।', NULL, '2026-04-30 08:02:29.639989+00', '2026-04-30 08:05:41.726+00');
