INSERT INTO public."serviceStatusHistory" VALUES ('ac2be28d-52db-4563-8f22-4bb7be8611cd', 'SEUZ7QWQMY', NULL, 'custom', '‎আপনার পন্যটির সমস্যা খুঁজে বের করা হয়েছে ‎', '‎আপনার আই পি এস টির ত্রুটি খুঁজে বের করা হয়েছে হাই ভোল্টেজ প্রবেশ করে ও কাস্টমার হাইচার্জ মুড রেগুলার চালু করে রেখেছিল যার কানের সার্কিট ক্যাপাসিটর ব্লাস্ট হয়েছেআমাদের সার্ভিস টিম খুব দ্রুত সমাধান করে আই পি এস টি রানিং করবে, আমাদের সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ।
INSERT INTO public."serviceStatusHistory" VALUES ('9a9990e2-da13-4472-834f-1be6b4eac017', 'SEUZ7QWQMY', NULL, 'custom', 'আই পি এসটির ত্রুটি সারানেরার কাজ চলছে ‎', 'আপনার আই পি এসটির যে ত্রুটি দরা পরেছে তা সারানোর কাজ শুরু করেছে আশা করছি নতুন সার্কিট  পরির্বতন করা হবে। আই পি এসটি রানিং হয়ে যাবে সময় দিয়ে সহযোগীতা করবেন ধন্যবাদ।
INSERT INTO public."serviceStatusHistory" VALUES ('11f11639-17e8-431b-9d70-934c7b9b601f', 'SEUZ7QWQMY', NULL, 'custom', 'কাস্টমার ওয়ারেন্টি ওয়ারনিং ', 'প্রিয় গ্রাহক EMON AHMED, আপনার  সার্ভিস আই ডি: SEUZ7QWQMY পন্যটির ভুল অপব্যবহার করা হয়েছে ।যার ফলে সাকিট এর সকল পার্টস ব্লাস্ট হয়েছে পুনরায় এমন ভুল অপব্যবহার করা হলে আপনার ওয়ারেন্টি বাতিল করা হবে আশা করি আই পি এসের সাথে দেওয়া ম্যানুয়াল বইটি পড়ে ব্যবহারবিধি দেখে ব্যবহার করবেন  ধন্যাবাদ।', NULL, '2026-05-09 12:46:22.571634+00', '2026-05-09 12:46:22.571634+00');
INSERT INTO public."serviceStatusHistory" VALUES ('680bace7-ce7c-4a28-b5ec-fc034fec0ef0', 'SEY2J35AF4', NULL, 'custom', 'আই পি এসটির কোন সমস্যা খুজেঁ পাওয়া যায়নি', 'আপনার আই পি এস টি আমাদের অফিসিয়াল দক্ষ ইঞ্জিনিয়ার টিম পরিক্ষা নিরিক্ষার করে কোন সমস্যা পাইনি আপনার অভিযোগ কারেন্ট চলে গেলে নো ফিডব্যাক ‍আসে সার্ভিস টিম সমস্যাটি পাইনি আরও গভির পর্যালোচনা করে দেখবে ধন্যবাদ।', NULL, '2026-05-10 17:17:21.358703+00', '2026-05-10 17:18:55.208+00');
INSERT INTO public."serviceStatusHistory" VALUES ('c1600f03-9e79-46fe-97c1-7aaa84b6ca47', 'SEY2J35AF4', NULL, 'custom', 'আইপি এসটি পুনরায় রিটেস্ট করা হচ্ছে ', 'প্রিয় গ্রাহক আপনার আইপি এসটি পুনরায় রিটেস্ট করা হচ্ছে আপনার দেওয়া অভিযোগ এর সমস্যাটি খুঁজে বের করতে নতুন করে পরিক্ষা নিরিক্ষা করা হচ্ছে। গতকাল সার্ভিস টিম এই সমস্যাটি খুঁজে পাইনি তাই পুনরায় আই পি এস টি সার্কিট উৎপাদন বিভাগের টিমকে দেওয়া হয়েছে আশা করছি ২/৩ ঘন্টার মধ্যে সমস্যাটা কি বুজতে পারব। সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ। ', NULL, '2026-05-11 05:19:26.221466+00', '2026-05-11 05:19:26.221466+00');
INSERT INTO public."serviceStatusHistory" VALUES ('3815040a-b2dc-41a7-bc83-75a75bec3bc3', 'SEUZ7QWQMY', NULL, 'custom', 'এস ই ইলেকট্রনিকস সার্ভিসিং সেন্টার নোট ‎', '‎আপনার আই পি এসটির কাজ সম্পূর্ণ করা হয়েছে এখন বর্তমানে ওয়েটিং টেস্টে আছে টেস্টিং শেষ হলেই আপনাকে সার্ভিস ট্রেকিং এর মাধ্যমে জানানো হবে সময় দিয়ে সহযোগীতা করবেন।
