INSERT INTO public."serviceStatusHistory" VALUES ('f3cf37df-9fe0-4fa3-bde8-467643320ef1', 'SE517KQQON', NULL, 'custom', 'সার্ভিস সেন্টার টেকনিশিয়ান নোট', 'প্রিয় গ্রাহক Md Mizan , আপনার পন্যটির সার্ভিস কমপ্লিট করতে আপনার আইপি এসটির সার্কিটের সাইজ আগেরটার চেয়ে বড় হবার কারনে ব্যাটারীর তার ও কুলিং ফ্যান জায়গা কিছুটা পরির্বতন করার লাগবে নতুন সার্কিটটি ইনস্টল করতে।', NULL, '2026-05-21 16:22:48.603407+00', '2026-05-21 16:22:48.603407+00');
INSERT INTO public."serviceStatusHistory" VALUES ('e18259f1-c5b6-4504-8ea6-4f135cd45bf1', 'SE517KQQON', NULL, 'custom', 'এস ই ইলেকট্রনিকস সার্ভিসিং সেন্টার নোট', 'আপনার আই পি এসটির সার্কিট ইন্সটল এর কাজ সম্পূর্ণ করা হয়েছে এখন বর্তমানে ওয়েটিং টেস্টে আছে টেস্টিং শেষ হলেই আপনাকে সার্ভিস ট্রেকিং এর মাধ্যমে জানানো হবে সময় দিয়ে সহযোগীতা করবেন।', NULL, '2026-05-21 18:31:08.947422+00', '2026-05-21 18:31:08.947422+00');
INSERT INTO public."serviceStatusHistory" VALUES ('9d7b8799-005f-4974-877e-3e412afbffa5', 'SE517KQQON', NULL, 'custom', 'সার্ভিস সেন্টার পন্যটির  টেস্টিং সাকসেসফুল', '‎প্রিয় গ্রাহক আপনার আই পি এস টি সম্পূর্ণভাবে সার্ভিসিং করে সকল প্রকারের টেস্টিং করা শেষ হয়েছে আমরা আপনার আই পি এস টি ডেলিভারি দিতে এস ই ইলেকট্রনিকস সার্ভিস সেন্টার প্রস্তুত আছে
INSERT INTO public."serviceStatusHistory" VALUES ('6b7548fa-e3bd-49e7-ba6c-3d5af6a13cb1', 'SE517KQQON', NULL, 'custom', 'সার্ভিস সেন্টার পণ্যটি ডেলিভারী দিতে প্রস্তুত', '‎প্রিয় গ্রাহক রাফছানুল, আপনার পন্যটির সার্ভিস আই ডি: SE517KQQON আমাদের অফিসিয়াল সার্ভিস পয়েন্ট আই পি এসটি ডেলিভারী দিতে সম্পূর্ণ প্রস্তুত আছে আপনাকে অতি দ্রুত ডেলিভারী নিতে অনুরোধ করা হল।
INSERT INTO public."serviceStatusHistory" VALUES ('fbd5fe32-f451-425b-b2bf-1c4dfcaea2e1', 'SE517KQQON', NULL, 'custom', 'আই পি এস টি ডেরিভারী নিতে অনুরোধ করা হল। ‎', '‎প্রিয় গ্রাহক আপনার পণ্যের সার্ভিস ডি: SE517KQQON এয়ারপোর্ট রোড বাদাম বাগিচা ২ নং রোড এস ই ইলেকট্রনিকস সার্ভিস পয়েন্ট থেকে আই পি এসটি ডেলিভারী নিতে অনুরোধ করা হচ্ছে ধন্যবাদ।
