INSERT INTO public."serviceStatusHistory" VALUES ('0585e6c3-d3b4-4207-8162-3fb8f63cae6d', 'SERA2FEU1H', NULL, 'custom', 'পন্যটির সমস্যা সমাধানে পরিক্ষা শুরু করেছে', '‎আপনার আই পি এস টি আমাদের অফিসিয়াল দক্ষ ইঞ্জিনিয়ার টিম পরিক্ষা নিরিক্ষার কাজ শুরু করেছে আশা করছি খুব দ্রুত সমস্যাটি খুঁজে বের করবে। সেই পর্যন্ত আমাদের সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ', NULL, '2026-07-31 12:12:33.334305+00', '2026-07-31 12:12:33.334305+00');
INSERT INTO public."serviceStatusHistory" VALUES ('07355fb0-6daf-48d1-b5d5-b0b7972c8b5d', 'SERA2FEU1H', NULL, 'custom', '‎আপনার পন্যটির সমস্যা খুঁজে বের করা হয়েছে', 'আপনার আই পি এস টির ত্রুটি খুঁজে বের করা হয়েছে আমাদের সার্ভিস টিম খুব দ্রুত সমাধান করে আই পি এস টি রানিং করবে, আমাদের সময় দিয়ে সহযোগিতা করবেন ধন্যবাদ।', NULL, '2026-07-31 12:13:23.267257+00', '2026-07-31 12:13:23.267257+00');
INSERT INTO public."serviceStatusHistory" VALUES ('48c26f2b-dfc1-4d53-8936-3bbd0217efc6', 'SERA2FEU1H', NULL, 'custom', '‎আই পি এসটির ত্রুটি সারানেরার কাজ চলছে', '‎আপনার আই পি এসটির যে ত্রুটি দরা পরেছে তা সারানোর কাজ শুরু করেছে আশা করছি নতুন পাটর্স গুলা পরির্বতন করলে আই পি এসটি রানিং হয়ে যাবে ,সময় দিয়ে সহযোগীতা করবেন ধন্যবাদ।
INSERT INTO public."serviceStatusHistory" VALUES ('273ffe18-a964-40d4-844e-bc94baddf1b0', 'SERA2FEU1H', NULL, 'custom', '‎এস ই ইলেকট্রনিকস সার্ভিসিং সেন্টার নোট ‎', 'আপনার আই পি এসটির কাজ সম্পূর্ণ করা হয়েছে এখন বর্তমানে ওয়েটিং টেস্টে আছে টেস্টিং শেষ হলেই আপনাকে সার্ভিস ট্রেকিং এর মাধ্যমে জানানো হবে সময় দিয়ে সহযোগীতা করবেন।
INSERT INTO public."serviceStatusHistory" VALUES ('e34f6c90-d7ed-4995-baa5-54a604df5e75', 'SERA2FEU1H', NULL, 'custom', '‎সার্ভিস সেন্টার পন্যটির  টেস্টিং সাকসেসফুল ‎', '‎প্রিয় গ্রাহক আপনার আই পি এস টি সম্পূর্ণভাবে সার্ভিসিং করে সকল প্রকারের টেস্টিং করা শেষ হয়েছে আমরা আপনার আই পি এস টি ডেলিভারি দিতে এস ই ইলেকট্রনিকস সার্ভিস সেন্টার প্রস্তুত আছে
INSERT INTO public."serviceStatusHistory" VALUES ('24a177d8-06a2-45e1-9a45-d1bf57aff471', 'SERA2FEU1H', NULL, 'custom', 'সার্ভিস সেন্টার পণ্যটি ডেলিভারী দিতে প্রস্তুত', 'প্রিয় গ্রাহক রাফছানুল, আপনার পন্যটির সার্ভিস আই ডি: SEYMLA0SYF আমাদের অফিসিয়াল সার্ভিস পয়েন্ট আই পি এসটি ডেলিভারী দিতে সম্পূর্ণ প্রস্তুত আছে আপনাকে অতি দ্রুত ডেলিভারী নিতে অনুরোধ করা হল।
